"use strict";(globalThis.webpackChunkaam_docs=globalThis.webpackChunkaam_docs||[]).push([[6896],{7888(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"aam-v1.1","metadata":{"permalink":"/es/blog/aam-v1.1","editUrl":"https://github.com/ininids/aam/blog/2026-05-15-aam-v1.1.md","source":"@site/i18n/es/docusaurus-plugin-content-blog/2026-05-15-aam-v1.1.md","title":"AAM v1.1 \u2014 Comillas en Listas, Multil\xednea y M\xe1s","description":"AAM v1.1 trae mejoras de calidad de vida: elementos entre comillas en listas, objetos en l\xednea, resoluci\xf3n de rutas relativas y un formateador integrado.","date":"2026-05-15T00:00:00.000Z","tags":[{"inline":false,"label":"AAM","permalink":"/es/blog/tags/aam","description":"AAM tag description"},{"inline":false,"label":"Feature","permalink":"/es/blog/tags/feature","description":"Feature tag description"}],"readingTime":0.83,"hasTruncateMarker":true,"authors":[{"name":"Nikita Goncharov","title":"AAM author","url":"https://www.ininids.in.rs","page":{"permalink":"/es/blog/authors/i-ni-ni-ds"},"socials":{"telegram":"https://t.me/ininids","github":"https://github.com/ininids","newsletter":"https://www.ininids.in.rs"},"imageURL":"https://github.com/INiNiDS.png","key":"INiNiDS"}],"frontMatter":{"slug":"aam-v1.1","title":"AAM v1.1 \u2014 Comillas en Listas, Multil\xednea y M\xe1s","authors":["INiNiDS"],"tags":["aam","feature"]},"unlisted":false,"nextItem":{"title":"LLMs y Robots","permalink":"/es/blog/llms-and-robots"}},"content":"AAM v1.1 trae mejoras de calidad de vida: elementos entre comillas en listas, objetos en l\xednea, resoluci\xf3n de rutas relativas y un formateador integrado.\\n\\n\x3c!--truncate--\x3e\\n\\n## Novedades en v1.1\\n\\n### Elementos entre Comillas en Listas\\n\\nLos elementos de lista ahora se pueden envolver entre comillas dobles (`\\"`) o simples (`\'`). Las comas dentro de elementos entre comillas se manejan correctamente:\\n\\n```aam\\nitems = [\\"rust, aam\\", \'single, quoted\', plain_value]\\n```\\n\\n### Objetos en L\xednea\\n\\nLos valores ahora pueden ser objetos en l\xednea:\\n\\n```aam\\nserver = { host = \\"localhost\\", port = 8080, debug = true }\\nconfig = { database = { host = \\"db.local\\", port = 5432 } }\\n```\\n\\n### Directivas Multil\xednea\\n\\nSe ha mejorado el manejo de bloques `@schema`, `@type` y otros que ocupan varias l\xedneas:\\n\\n```aam\\n@schema Player {\\n    name: string\\n    score: i32\\n    tags: list<string>\\n}\\n```\\n\\n### Rutas Relativas\\n\\nLas rutas en `@import` y `@derive` ahora se resuelven relativas al archivo:\\n\\n```aam\\n@import ./schemas/base.aam\\n@derive ./types/player.aam::Player\\n```\\n\\n### Formateador Integrado\\n\\nEl formateador da formato autom\xe1tico a los archivos: colapsado inteligente de esquemas, elevaci\xf3n de directivas, sangr\xeda configurable.\\n\\n---\\n\\nM\xe1s detalles en la [documentaci\xf3n actualizada](/docs/using/types)."},{"id":"llms-and-robots","metadata":{"permalink":"/es/blog/llms-and-robots","editUrl":"https://github.com/ininids/aam/blog/2026-03-4-update.md","source":"@site/i18n/es/docusaurus-plugin-content-blog/2026-03-4-update.md","title":"LLMs y Robots","description":"Viene una nueva actualizaci\xf3n con los nuevos archivos llms.txt y robots.txt para motores de b\xfasqueda e IA.","date":"2026-03-04T00:00:00.000Z","tags":[{"inline":false,"label":"AAM","permalink":"/es/blog/tags/aam","description":"AAM tag description"},{"inline":false,"label":"Update","permalink":"/es/blog/tags/update","description":"Update tag description"}],"readingTime":0.12,"hasTruncateMarker":false,"authors":[{"name":"Nikita Goncharov","title":"AAM author","url":"https://www.ininids.in.rs","page":{"permalink":"/es/blog/authors/i-ni-ni-ds"},"socials":{"telegram":"https://t.me/ininids","github":"https://github.com/ininids","newsletter":"https://www.ininids.in.rs"},"imageURL":"https://github.com/INiNiDS.png","key":"INiNiDS"}],"frontMatter":{"slug":"llms-and-robots","title":"LLMs y Robots","authors":["INiNiDS"],"tags":["aam","update"]},"unlisted":false,"prevItem":{"title":"AAM v1.1 \u2014 Comillas en Listas, Multil\xednea y M\xe1s","permalink":"/es/blog/aam-v1.1"},"nextItem":{"title":"Empezando con AAM","permalink":"/es/blog/starting-aam"}},"content":"Viene una nueva actualizaci\xf3n con los nuevos archivos llms.txt y robots.txt para motores de b\xfasqueda e IA.\\nY se agregaron [ejemplos](@site/docs/examples.md)"},{"id":"starting-aam","metadata":{"permalink":"/es/blog/starting-aam","editUrl":"https://github.com/ininids/aam/blog/2026-03-2-first-blog-post.md","source":"@site/i18n/es/docusaurus-plugin-content-blog/2026-03-2-first-blog-post.md","title":"Empezando con AAM","description":"\xa1Empecemos con AAM!","date":"2026-03-02T00:00:00.000Z","tags":[{"inline":false,"label":"AAM","permalink":"/es/blog/tags/aam","description":"AAM tag description"}],"readingTime":0.34,"hasTruncateMarker":true,"authors":[{"name":"Nikita Goncharov","title":"AAM author","url":"https://www.ininids.in.rs","page":{"permalink":"/es/blog/authors/i-ni-ni-ds"},"socials":{"telegram":"https://t.me/ininids","github":"https://github.com/ininids","newsletter":"https://www.ininids.in.rs"},"imageURL":"https://github.com/INiNiDS.png","key":"INiNiDS"}],"frontMatter":{"slug":"starting-aam","title":"Empezando con AAM","authors":["INiNiDS"],"tags":["aam"]},"unlisted":false,"prevItem":{"title":"LLMs y Robots","permalink":"/es/blog/llms-and-robots"}},"content":"\xa1Empecemos con AAM!\\n\\n## \xbfAAM?\\n\\n\x3c!--truncate--\x3e\\n\\nModerno,  \\nF\xe1cil,  \\nEl mejor  \\nAAM es un formato de alias realmente bueno  \\n\xbfNecesitas una configuraci\xf3n f\xe1cil? OK  \\n\xbfNecesitas un an\xe1lisis r\xe1pido? OK  \\n\xbfNecesitas seguridad de tipos? OK  \\n\xbfNecesitas transformar de dif\xedcil a f\xe1cil? OKKKKKKK\\n\\n## Ejemplo\\n\\n```aam\\nhost = localhost\\nport = 8080\\n```\\n\\nEso es todo. Si dices `localhost` obtendr\xe1s `host` de la configuraci\xf3n.\\n\\"\xbfQu\xe9 es localhost? Es un \\\\{AAM::get(\\"localhost\\")\\\\}\\"\\nRealmente f\xe1cil, \xbfs\xed?"}]}}')}}]);